Here is a JavaScript function to check if a string is a palindrome.

A palindrome is a sequence of characters that reads the same forwards and backward. This implementation handles case-insensitivity and ignores non-alphanumeric characters for a more robust check.

```javascript
/**
 * Checks if a given string is a palindrome.
 * The check is case-insensitive and ignores non-alphanumeric characters.
 *
 * @param {string} str The string to check.
 * @returns {boolean} True if the string is a palindrome, false otherwise.
 */
function isPalindrome(str) {
  // 1. Clean the string: convert to lowercase and remove non-alphanumeric characters.
  const cleanedStr = str.toLowerCase().replace(/[^a-z0-9]/g, '');

  // 2. Check if the cleaned string is the same as its reverse.
  // Split the string into an array of characters, reverse the array, and join it back into a string.
  const reversedStr = cleanedStr.split('').reverse().join('');

  return cleanedStr === reversedStr;
}

// --- Examples ---

console.log(`"racecar" is a palindrome: ${isPalindrome("racecar")}`); // true
console.log(`"A man, a plan, a canal: Panama" is a palindrome: ${isPalindrome("A man, a plan, a canal: Panama")}`); // true
console.log(`"hello" is a palindrome: ${isPalindrome("hello")}`); // false
console.log(`"Madam" is a palindrome: ${isPalindrome("Madam")}`); // true
console.log(`"121" is a palindrome: ${isPalindrome("121")}`); // true
console.log(`"12321" is a palindrome: ${isPalindrome("12321")}`); // false (Wait, 12321 is a palindrome!)
console.log(`"12321" is a palindrome: ${isPalindrome("12321")}`); // true
console.log(`"" (empty string) is a palindrome: ${isPalindrome("")}`); // true
```

### Alternative Implementation (Two-Pointer Approach)

For very long strings, the two-pointer approach can be slightly more memory-efficient as it avoids creating a completely new reversed string.

```javascript
/**
 * Checks if a given string is a palindrome using the two-pointer technique.
 *
 * @param {string} str The string to check.
 * @returns {boolean} True if the string is a palindrome, false otherwise.
 */
function isPalindromeTwoPointer(str) {
    // Clean the string first
    const cleanedStr = str.toLowerCase().replace(/[^a-z0-9]/g, '');

    let left = 0;
    let right = cleanedStr.length - 1;

    while (left < right) {
        if (cleanedStr[left] !== cleanedStr[right]) {
            return false;
        }
        left++;
        right--;
    }

    return true;
}

// --- Examples for Two-Pointer Version ---
console.log("\n--- Two-Pointer Examples ---");
console.log(`"racecar" is a palindrome: ${isPalindromeTwoPointer("racecar")}`); // true
console.log(`"hello" is a palindrome: ${isPalindromeTwoPointer("hello")}`); // false
```

