This method uses a loop and is generally the most efficient for calculating Fibonacci numbers because it avoids redundant calculations inherent in naive recursion.

```javascript
/**
 * Calculates the n-th Fibonacci number using an iterative approach.
 * The sequence starts with F(0) = 0 and F(1) = 1.
 *
 * @param {number} n The index of the Fibonacci number to find (must be a non-negative integer).
 * @returns {number} The n-th Fibonacci number.
 * @throws {Error} If n is negative.
 */
function fibonacciIterative(n) {
    if (n < 0) {
        throw new Error("Input must be a non-negative integer.");
    }
    if (n === 0) {
        return 0;
    }
    if (n === 1) {
        return 1;
    }

    let a = 0;
    let b = 1;
    let result = 0;

    // Start loop from i=2 up to n
    for (let i = 2; i <= n; i++) {
        result = a + b;
        // Shift the values for the next iteration
        a = b;
        b = result;
    }

    return result;
}

