Here is a JavaScript function that performs a deep clone of an object.

For a truly robust deep clone, especially one that handles complex types like `Date`, `RegExp`, `Map`, `Set`, and circular references, a more sophisticated approach is needed. However, the following implementation provides a solid deep clone for plain JavaScript objects and arrays, which is the most common requirement.

```javascript
/**
 * Performs a deep clone of an object or array.
 *
 * This function handles plain objects and arrays recursively. It does not
 * handle complex types like functions, Symbols, Map, Set, or circular references.
 *
 * @param {*} obj The object or value to clone.
 * @returns {*} A deep clone of the input object.
 */
function deepClone(obj) {
    // 1. Handle primitives and null
    if (obj === null || typeof obj !== 'object') {
        return obj;
    }

    // 2. Handle Date objects
    if (obj instanceof Date) {
        return new Date(obj.getTime());
    }

    // 3. Handle RegExp objects
    if (obj instanceof RegExp) {
        return new RegExp(obj.source, obj.flags);
    }

    // 4. Handle Arrays and Objects
    if (Array.isArray(obj)) {
        const clonedArray = [];
        for (let i = 0; i < obj.length; i++) {
            clonedArray[i] = deepClone(obj[i]);
        }
        return clonedArray;
    }

    // 5. Handle plain Objects
    if (typeof obj === 'object') {
        const clonedObject = {};
        for (const key in obj) {
            // Ensure we only copy own properties, not inherited ones
            if (Object.prototype.hasOwnProperty.call(obj, key)) {
                clonedObject[key] = deepClone(obj[key]);
            }
        }
        return clonedObject;
    }

    // Fallback for any other complex types not explicitly handled (e.g., functions, etc.)
    // For functions, this returns the original function reference.
    return obj;
}

// --- Example Usage ---

const originalObject = {
    a: 1,
    b: "hello",
    c: [1, { nested: true, value: 42 }],
    d: new Date(),
    e: /test/gi,
    f: null
};

const clonedObject = deepClone(originalObject);

console.log("Original Object:", originalObject);
console.log("Cloned Object:", clonedObject);

// Test for deep copy verification: Modify the clone
clonedObject.c[1].value = 999;
clonedObject.a = 100;

console.log("\n--- Verification ---");
console.log("Original Object (after modification):", originalObject);
console.log("Cloned Object (after modification):", clonedObject);

// Check if the nested object in the clone is different from the original
