console.log("Is primitive 'a' different?", originalObject.a !== clonedObject.a); // Should be true
```

Here is a JavaScript function that counts the words in a given string.

This implementation handles various forms of whitespace (spaces, tabs, newlines) and filters out empty strings that might result from multiple spaces.

```javascript
/**
 * Counts the number of words in a given string.
 * Words are defined as sequences of non-whitespace characters separated by whitespace.
 *
 * @param {string} text The input string to analyze.
 * @returns {number} The total number of words in the string.
 */
function countWords(text) {
  if (typeof text !== 'string' || text.trim() === '') {
    return 0;
  }

  // 1. Use the split method with a regular expression to split the string by any whitespace.
  // The regex /\s+/ matches one or more whitespace characters (spaces, tabs, newlines).
  const wordsArray = text.trim().split(/\s+/);

  // 2. Return the length of the resulting array.
  return wordsArray.length;
}

// --- Examples ---

console.log(`"Hello world": ${countWords("Hello world")}`); // Output: 2
console.log(`"  Multiple   spaces here ": ${countWords("  Multiple   spaces here ")}`); // Output: 3
console.log(`"One\nTwo\tThree": ${countWords("One\nTwo\tThree")}`); // Output: 3
console.log(`"": ${countWords("")}`); // Output: 0
console.log(`"   ": ${countWords("   ")}`); // Output: 0
console.log(`"SingleWord": ${countWords("SingleWord")}`); // Output: 1
```

Here is a JavaScript function to capitalize the first letter of each word in a given string.

```javascript
/**
 * Capitalizes the first letter of each word in a string.
 *
 * @param {string} str The input string to be capitalized.
 * @returns {string} The string with the first letter of each word capitalized.
 */
function capitalizeWords(str) {
  if (!str) {
    return "";
  }

  // 1. Split the string by spaces to get an array of words.
  const wordsArray = str.split(' ');

  // 2. Map over the array, capitalizing the first letter of each word.
  const capitalizedWords = wordsArray.map(word => {
    // Handle empty strings that might result from multiple spaces
    if (word.length === 0) {
      return '';
    }
    // Capitalize the first letter and concatenate the rest of the word (in lowercase)
    const firstLetter = word.charAt(0).toUpperCase();
    const restOfWord = word.slice(1).toLowerCase();
    return firstLetter + restOfWord;
  });

  // 3. Join the array back into a single string with spaces.
  return capitalizedWords.join(' ');
}

// Example Usage:
const sentence1 = "hello world, this is a test";
const result1 = capitalizeWords(sentence1);
console.log(`Original: "${sentence1}"`);
console.log(`Capitalized: "${result1}"`); // Output: "Hello World, This Is A Test"

const sentence2 = "javascript function example";
const result2 = capitalizeWords(sentence2);
console.log(`\nOriginal: "${sentence2}"`);
console.log(`Capitalized: "${result2}"`); // Output: "Javascript Function Example"

const sentence3 = "  leading and trailing spaces ";
const result3 = capitalizeWords(sentence3);
console.log(`\nOriginal: "${sentence3}"`);
console.log(`Capitalized: "${result3}"`); // Output: "  Leading And Trailing Spaces "
```

Here is a JavaScript function that uses the `fetch` API to retrieve JSON data from a given URL and returns the parsed JSON object.

```javascript
/**
 * Fetches JSON data from a specified URL and returns the parsed JSON object.
 *
 * @param {string} url The URL from which to fetch the data.
 * @returns {Promise<object>} A Promise that resolves with the parsed JSON data.
 * @throws {Error} Throws an error if the network request fails or the response is not OK.
 */
async function fetchJsonData(url) {
  try {
    // 1. Perform the fetch request
    const response = await fetch(url);

    // 2. Check if the request was successful (status code 200-299)
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status} for URL: ${url}`);
    }

    // 3. Parse the response body as JSON
    const data = await response.json();

    // 4. Return the parsed data
    return data;
  } catch (error) {
    console.error("Error fetching JSON data:", error.message);
    // Re-throw the error so the calling function can handle it
    throw error;
  }
}

// --- Example Usage ---
async function main() {
  const apiUrl = 'https://jsonplaceholder.typicode.com/todos/1'; // A public test API

  console.log(`Attempting to fetch data from: ${apiUrl}`);

  try {
    const todoItem = await fetchJsonData(apiUrl);
    console.log("\n--- Successfully Fetched Data ---");
    console.log("Type of data received:", typeof todoItem);
    console.log("Todo Title:", todoItem.title);
    console.log("User ID:", todoItem.userId);

  } catch (error) {
    console.log("\n--- Failed to complete the operation ---");
    console.log("Operation failed. Check the error message above.");
  }
}

main();
```

