/**
 * Flattens a nested array into a single-level array.
 *
 * @param {Array<any>} arr The nested array to flatten.
 * @returns {Array<any>} A new, one-dimensional array.
 */
function flattenArray(arr) {
  const flattened = [];

  for (const element of arr) {
    if (Array.isArray(element)) {
      // If the element is an array, recursively call flattenArray
      // and concatenate the result to the current flattened array.
      const subArray = flattenArray(element);
      flattened.push(...subArray);
    } else {
      // If the element is not an array, just push it.
      flattened.push(element);
    }
  }

  return flattened;
}

