console.log(`invalid-email: ${validateEmail("invalid-email")}`); // false (missing @ and domain)
console.log(`@missinguser.com: ${validateEmail("@missinguser.com")}`); // false (missing local part)
console.log(`user@.com: ${validateEmail("user@.com")}`); // false (domain starts with dot)
console.log(`user@domain: ${validateEmail("user@domain")}`); // false (missing TLD)
console.log(`user@domain.c: ${validateEmail("user@domain.c")}`); // true (TLD length check is 2 or more)
