/**
 * Creates a throttled version of a function that only invokes it at most once per every wait milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {Function} A new function that throttles the original function.
 */
function throttle(func, wait) {
    let timeout = null;
    let lastArgs = null;
    let lastThis = null;
    let lastExecTime = 0;

    return function(...args) {
        const context = this;
        const now = Date.now();

        // Check if enough time has passed since the last execution
        if (now - lastExecTime >= wait) {
            // Execute immediately
            lastExecTime = now;
            func.apply(context, args);
        } else if (!timeout) {
            // If we are within the wait period but no timeout is scheduled,
            // schedule a call for when the wait period is over.
            timeout = setTimeout(() => {
                lastExecTime = Date.now();
                timeout = null;
                func.apply(context, lastArgs);
            }, wait - (now - lastExecTime));
        } else {
            // If a timeout is already scheduled, just update the arguments
            // to be used in the next execution.
            lastArgs = args;
            lastThis = context;
        }
    };
