 * @param func The function to debounce.
 * @param delay The number of milliseconds to wait after the last call before executing func.
 * @returns A new function that is the debounced version of the input function.
 */
function debounce<T extends (...args: any[]) => any>(
  func: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  return function(this: ThisParameterType<T>, ...args: Parameters<T>): void {
    // 1. Clear the previous timeout if it exists
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    // 2. Set a new timeout
    timeoutId = setTimeout(() => {
      // Execute the original function with the correct context and arguments
      func.apply(this, args);
      timeoutId = null; // Clear the ID after execution
    }, delay);
  };
}

// --- Example Usage ---

// 1. Define the function we want to debounce
function handleSearch(query: string): void {
  console.log(`Searching for: ${query}`);
}

// 2. Create the debounced version
const debouncedSearch = debounce(handleSearch, 500); // 500ms delay

// 3. Simulate rapid calls (e.g., user typing in a search box)
console.log("Simulating rapid input...");
debouncedSearch("a");
debouncedSearch("ap");
debouncedSearch("app");
debouncedSearch("appl");
debouncedSearch("apple"); // This call will be the one that eventually execute

// Wait a moment to see the output (in a real browser/Node environment)
setTimeout(() => {
    console.log("\n--- Second set of calls ---");
    debouncedSearch("banana");
}, 1000);
```

