Here is a TypeScript function that counts the words in a given string.

This implementation handles various forms of whitespace (spaces, tabs, newlines) by splitting the string based on any sequence of whitespace characters.

```typescript
/**
 * Counts the number of words in a given string.
 * A word is defined as any sequence of non-whitespace characters separated by whitespace.
 *
 * @param text The input string to analyze.
 * @returns The number of words in the string. Returns 0 if the input is null, undefined, or empty.
 */
function countWords(text: string | null | undefined): number {
    if (!text) {
        return 0;
    }

    // 1. Trim leading/trailing whitespace to avoid counting empty strings at the start/end.
    const trimmedText = text.trim();

    // 2. If the string is empty after trimming, there are no words.
    if (trimmedText.length === 0) {
        return 0;
    }

    // 3. Split the string by one or more whitespace characters (\s+).
    // The filter(Boolean) step removes any empty strings that might result from
    // multiple spaces between words (though .trim() helps significantly).
    const wordsArray: string[] = trimmedText.split(/\s+/).filter(word => word.length > 0);

    return wordsArray.length;
}

// --- Examples ---

console.log(`"Hello world": ${countWords("Hello world")}`); // Output: 2
console.log(`"  leading and trailing spaces  ": ${countWords("  leading and trailing spaces  ")}`); // Output: 4
console.log(`"Multiple   spaces   here": ${countWords("Multiple   spaces   here")}`); // Output: 3
console.log(`"": ${countWords("")}`); // Output: 0
console.log(`"   \t\n ": ${countWords("   \t\n ")}`); // Output: 0
console.log(`null: ${countWords(null)}`); // Output: 0
console.log(`undefined: ${countWords(undefined)}`); // Output: 0
console.log(`"One\nTwo\tThree": ${countWords("One\nTwo\tThree")}`); // Output: 3
```

