/**
 * Groups an array of objects by a specified key.
 *
 * @template T The type of the objects in the array.
 * @template K The type of the key to group by.
 * @param {T} arr The array of objects to group.
 * @param {keyof T} key The key in the objects to group by.
 * @returns {Record<string, T[]>} An object where keys are the unique values of the grouping key,
 *          and values are arrays of objects that share that key value.
 */
function groupBy<T extends Record<string, any>, K extends keyof T>(
  arr: T[],
  key: K
): Record<string, T[]> {
  return arr.reduce((acc: Record<string, T[]>, current: T) => {
    // Get the value of the grouping key for the current object
    const groupKey = current[key];

    // Initialize the array for this group if it doesn't exist
    if (!acc[groupKey]) {
      acc[groupKey] = [];
    }

    // Push the current object into the appropriate group
    acc[groupKey].push(current);

    return acc;
  }, {} as Record<string, T[]>);
}

