const arr2: number[] = [-10, -5, -2, -8];
console.log(`The largest number in [${arr2}] is: ${findLargestNumber(arr2)}`); // Output: -2

const arr3: number[] = [5];
console.log(`The largest number in [${arr3}] is: ${findLargestNumber(arr3)}`); // Output: 5

const arr4: number[] = [];
console.log(`The largest number in [] is: ${findLargestNumber(arr4)}`); // Output: -Infinity

const arr5: number[] = [100, 200, 50];
console.log(`The largest number in [${arr5}] is: ${findLargestNumber(arr5)}`); // Output: 200
```

### Alternative using `Math.max` and the Spread Operator (More Concise)

For a more modern and concise solution, you can leverage the built-in `Math.max` function combined with the spread operator (`...`):

```typescript
/**
 * Finds the largest number in an array of numbers using Math.max.
 *
 * @param numbers An array of numbers to search through.
 * @returns The largest number in the array, or -Infinity if the array is empty.
 */
function findLargestNumberConcise(numbers: number[]): number {
  if (numbers.length === 0) {
    return -Infinity;
  }
  return Math.max(...numbers);
}

