/**
 * Reverses a null-terminated string in place.
 *
 * @param str The string to be reversed.
 */
void reverseStringInPlace(char *str) {
    if (str == NULL) {
        return; // Handle null pointer case
    }

    int start = 0;
    int end = strlen(str) - 1;
    char temp;

    // Loop until the start index is no longer less than the end index
    while (start < end) {
        // Swap the characters at the start and end positions
